#!/usr/bin/env bash
set -euo pipefail
echo "NO-GO Stage2 successor execution authority is not committed; historical body is evidence only" >&2; exit 2
C="${CEILING1_STAGE2_CONTAINER:?}"; ROOT="${CEILING1_ANALYSIS_ROOT:?}"; WT="${CEILING1_AUTOPILOT_REPO:?}"; ARM="${CEILING1_STAGE2_ARM:?}"; [[ "$ARM" == qwen3-1p7b ]] || { echo "NO-GO qwen3 reflector arm=$ARM" >&2; exit 2; }
UUID="${CEILING1_STAGE2_GPU_UUID:?}"; KIND="${CEILING1_STAGE2_KIND:?}"; EVI="${CEILING1_STAGE2_EVIDENCE:?}"; PRIOR="${CEILING1_STAGE2_PRIOR:?}"; OUT="${CEILING1_STAGE2_OUTPUT:?}"; STATE="${CEILING1_STAGE2_STATE_ID:?}"; ROUND="${CEILING1_STAGE2_ROUND:?}"; SD="${CEILING1_STAGE2_SD_ADAPTER:-}"; MEM="${CEILING1_STAGE2_MEMORY:-}"; SKILL="${CEILING1_STAGE2_SKILL:-}"; CONTRACT="${CEILING1_STAGE2_ARTIFACT_CONTRACT:-legacy-authoring-v1}"; SCOPE="${CEILING1_STAGE2_SCOPE_MANIFEST:-}"  # legacy-revision-compat
CORE=/workspace/control/openevo-core; MODEL="$ROOT/stage2-base/$ARM"; extra=(); [[ -n "$SD" ]] && extra+=(--sd-adapter "$SD"); [[ -n "$MEM" ]] && extra+=(--memory "$MEM"); [[ -n "$SKILL" ]] && extra+=(--skill "$SKILL"); [[ -n "$SCOPE" ]] && extra+=(--scope-manifest "$SCOPE")
state_mounts=(); for P in "$PRIOR" "$MEM" "$SKILL" "$SD" "$SCOPE"; do [[ -n "$P" ]] || continue; case "$P" in "$ROOT"/*) ;; *) state_mounts+=(-v "$P:$P:ro");; esac; done
OUTDIR="$(dirname "$OUT")"
docker run -d --name "$C" --restart no --tmpfs /tmp:rw,exec,nosuid,size=4g,mode=1777 --gpus "device=$UUID" --network none --user 1001:1001 -e CUDA_VISIBLE_DEVICES="$UUID" -e HOME=/tmp/openevo-home -e XDG_CACHE_HOME=/tmp/openevo-cache -e HF_HOME=/tmp/huggingface -e TRITON_CACHE_DIR=/tmp/triton -e TMPDIR=/tmp -e TORCHINDUCTOR_CACHE_DIR=/tmp/torchinductor_openevo -e PYTHONDONTWRITEBYTECODE=1 -e TRANSFORMERS_OFFLINE=1 -e HF_HUB_OFFLINE=1 -e PYTHONPATH="$CORE/src:$WT" -v "$CORE:$CORE:ro" -v "$WT:$WT:ro" -v "$ROOT:$ROOT:ro" "${state_mounts[@]}" -v "$(dirname "$EVI"):$(dirname "$EVI"):ro" -v "$OUTDIR:$OUTDIR" --entrypoint /usr/local/bin/python3 experiment-host/openevo-scientific:h144-runtime-v1 "$WT/scripts/openevo_webshop/ceiling1_stage2_reflector_qwen3.py" --kind "$KIND" --evidence "$EVI" --prior "$PRIOR" --model "$MODEL" --output "$OUT" --gpu-uuid "$UUID" --state-id "$STATE" --round-index "$ROUND" --artifact-contract "$CONTRACT" "${extra[@]}"  # legacy-revision-compat
